def kmp_table(p):
    t = [0] * len(p)
    k = 0
    for i in range(1, len(p)):
        while k > 0 and p[k] != p[i]:
            k = t[k - 1]
        if p[k] == p[i]:
            k += 1
        t[i] = k
    return t

def kmp_search(s, p):
    t = kmp_table(p)
    k = 0
    for i, c in enumerate(s):
        while k > 0 and p[k] != c:
            k = t[k - 1]
        if p[k] == c:
            k += 1
        if k == len(p):
            return i - k + 1
    return -1

import heapq

def dijkstra(graph, start):
    dist = {n: float('inf') for n in graph}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u].items():
            new = d + w
            if new < dist[v]:
                dist[v] = new
                heapq.heappush(pq, (new, v))
    return dist

